ures\":[\"Procure-to-pay chain\",\"Three-way matching\",\"Batch/lot/serial tracking\",\"Landed-cost allocation\",\"B2B trade portal\",\"Demand forecasting\"],\"faq\":[[\"Does it support three-way matching?\",\"Yes — PO, goods receipt and bill are matched before payment.\"],[\"Is there a B2B portal?\",\"Yes — trade customers can order online against their pricing and terms.\"]]},\"erp-crm-platform\":{\"h1\":\"ERP + CRM Platform\",\"lead\":\"One platform where CRM flows straight into orders, invoicing and the ledger.\",\"body\":[\"ECOM AE unifies CRM and ERP so leads, opportunities and pipeline connect directly to quotations, sales orders, delivery notes, invoices and the general ledger — no export/import between systems.\",\"With customer, sales and finance data in one model, the AI advisor reasons across the entire customer lifecycle.\"],\"features\":[\"Leads → opportunities → pipeline\",\"Quote → order → invoice\",\"Shared customer + finance data\",\"Customer timeline & activities\",\"Receivables & credit visibility\",\"AI customer insights\"],\"faq\":[[\"Is CRM separate from ERP here?\",\"No — CRM is a native layer of the same BOS, sharing one data model with finance and operations.\"],[\"Does CRM see receivables?\",\"Yes — credit exposure and payment history are always current because it is one platform.\"]]},\"inventory-management-software\":{\"h1\":\"Inventory Management Software\",\"lead\":\"Multi-warehouse inventory with a full transaction ledger, batch/lot/serial and barcode.\",\"body\":[\"ECOM AE provides multi-warehouse inventory with a complete transaction ledger (running balance on every movement), batch/lot and serial tracking, barcode scanning and weighted-average valuation.\",\"The AI advisor turns consumption into days-of-cover and recommends reorder quantities before items stock out.\"],\"features\":[\"Inventory transaction ledger\",\"Batch/lot & serial tracking\",\"Barcode scan lookup\",\"Multi-warehouse & transfers\",\"Weighted-average valuation\",\"Predictive reorder advisor\"],\"faq\":[[\"Does it track serial numbers?\",\"Yes — a serial register tracks each unit through its lifecycle (in stock → sold → returned).\"],[\"Is there a stock ledger?\",\"Yes — every movement is recorded with a running on-hand balance for full auditability.\"]]},\"procurement-software\":{\"h1\":\"Procurement Software\",\"lead\":\"From requisition to bill — RFQ, vendor comparison, goods receipt and three-way match.\",\"body\":[\"ECOM AE covers the enterprise procurement lifecycle: purchase requisition, RFQ to multiple vendors, a vendor comparison matrix, purchase orders, goods receipt notes, three-way matching and supplier bills.\",\"Approval thresholds route high-value purchases through the workflow engine, and supplier performance is tracked over time.\"],\"features\":[\"Requisition → RFQ → PO\",\"Vendor comparison matrix\",\"Goods receipt & three-way match\",\"Approval thresholds\",\"Supplier performance\",\"Contract purchasing\"],\"faq\":[[\"Can I compare vendor quotes?\",\"Yes — RFQs collect vendor quotations into a comparison matrix before you raise a PO.\"],[\"Are approvals enforced?\",\"Yes — high-value POs route through the configurable approval hierarchy.\"]]},\"accounting-software-uae\":{\"h1\":\"Accounting Software in the UAE\",\"lead\":\"Double-entry accounting with UAE VAT, dimensions, period locking and consolidation.\",\"body\":[\"ECOM AE delivers full double-entry accounting: chart of accounts, journal engine, financial dimensions (cost/profit centre, branch, project), fiscal periods with locking, multi-currency revaluation, fixed assets and consolidation.\",\"UAE VAT and Peppol e-invoicing are built in, and an immutable posting model with reversal-only corrections keeps the books audit-ready.\"],\"features\":[\"Double-entry GL + dimensions\",\"UAE VAT & Peppol e-invoicing\",\"Fiscal periods & locking\",\"Multi-currency revaluation\",\"Immutable posting + reversals\",\"Trial balance, P&L, balance sheet\"],\"faq\":[[\"Is it UAE VAT compliant?\",\"Yes — VAT, returns and Peppol e-invoicing are built into the accounting core.\"],[\"Can posted entries be edited?\",\"No — posting is immutable; corrections are made via reversal entries, preserving the audit trail.\"]]}}";

